package com.example.nativesso.childapp;
import android.util.Base64; import org.json.JSONObject; import java.nio.charset.StandardCharsets; import java.security.*; import java.security.spec.ECGenParameterSpec; import java.util.UUID;
public final class CryptoJwt {
 private static final String ALIAS="native_sso_child_key";
 public static void ensureKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return;KeyPairGenerator g=KeyPairGenerator.getInstance("EC","AndroidKeyStore");g.initialize(new android.security.keystore.KeyGenParameterSpec.Builder(ALIAS,3).setAlgorithmParameterSpec(new ECGenParameterSpec("secp256r1")).setDigests("SHA-256").build());g.generateKeyPair();}
 public static String publicJwkString()throws Exception{return jwk().toString();}
 public static String assertion(String cid,String aud)throws Exception{ensureKey();JSONObject h=new JSONObject().put("alg","ES256").put("typ","JWT").put("kid",SsoConfig.CLIENT_ID).put("jwk",jwk());long n=System.currentTimeMillis()/1000;JSONObject p=new JSONObject().put("iss",cid).put("sub",cid).put("aud",aud).put("jti",UUID.randomUUID().toString()).put("iat",n).put("exp",n+300);String a=b64(h.toString().getBytes(StandardCharsets.UTF_8)),b=b64(p.toString().getBytes(StandardCharsets.UTF_8));Signature s=Signature.getInstance("SHA256withECDSA");KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);s.initSign((PrivateKey)ks.getKey(ALIAS,null));s.update((a+"."+b).getBytes(StandardCharsets.US_ASCII));return a+"."+b+"."+der(s.sign());}
 private static JSONObject jwk()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);java.security.interfaces.ECPublicKey p=(java.security.interfaces.ECPublicKey)ks.getCertificate(ALIAS).getPublicKey();return new JSONObject().put("kty","EC").put("crv","P-256").put("kid",SsoConfig.CLIENT_ID).put("x",b64(u(p.getW().getAffineX().toByteArray()))).put("y",b64(u(p.getW().getAffineY().toByteArray())));}
 private static byte[] u(byte[] b){byte[] o=new byte[32];System.arraycopy(b,Math.max(0,b.length-32),o,Math.max(0,32-b.length),Math.min(32,b.length));return o;} private static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP|Base64.URL_SAFE|Base64.NO_PADDING);} private static String der(byte[] d){int rl=d[3]&255;int so=4+rl+2;int sl=d[so-1]&255;byte[]o=new byte[64];System.arraycopy(d,4+Math.max(0,rl-32),o,Math.max(0,32-(rl)),Math.min(32,rl));System.arraycopy(d,so+Math.max(0,sl-32),o,32+Math.max(0,32-sl),Math.min(32,sl));return b64(o);}
}
